  title: "Физика статичког електрицитета — зашто се коса наелектрише када скинемо зимску капу",
  readTimeMins: 18,
  audioFile: "audio/pm-06.m4a",
  audioText: "Физика статичког електрицитета — зашто се коса наелектрише када скинемо зимску капу. Трење вунене капе о косу преноси електроне, чинећи сваку влас негативно наелектрисаном, док међусобно одбијање истих набоја тера косу да лети увис.",
  text: `<b>Физика статичког електрицитета — зашто се коса наелектрише када скинемо зимску капу</b><br><br>
  Свима нам је позната она комична ситуација када након уласка са оштрог зимског ваздуха у топлу собу скинемо вунену капу, а коса нам се подигне и крене да лети на све стране, пркосећи гравитацији. Иза овог забавног призора стоји чиста физика статичког електрицитета.<br><br>
  У нормалном стању, предмети око нас и наша коса су електрично неутрални — имају савршен баланс позитивних и негативних честица. Међутим, када вунена капа протрља преко косе, долази до преноса невидљивих субатомских честица: <em>електрона</em>. Вуна лако отпушта своје електроне, док их људска коса савршено прима. Због овог вишка негативног набоја, свака појединачна влас постаје негативно наелектрисана.<br><br>
  Пошто се исти набоји (минус и минус) међусобно одбијају, појединачне власи почињу да беже једна од друге у свим правцима, формирајући облик попут „маслачка“. Гравитација ту губи битку јер је електромагнетна сила на микро нивоу неупоредиво јача. Ова појава је изражена зими зато што интензивно кућно грејање исушује ваздух, претварајући га у савршен изолатор који зароби електроне на нашој глави.`,
