  text: `<b>Зашто нам се појави „гушчја кожа“ (најежимо се од хладноће и страха)</b><br><br>
  Када нас изненади продорни мраз или када погледамо добар хорор филм, наше тело одмах реагује — кожа почиње да се „јежи“, а ситне избочине стварају ефекат познат као „гушчја кожа“. Овај необичан феномен дешава се потпуно ван наше свесне воље, под управом аутономног нервног система.<br><br>
  У корену сваке длачице на нашем телу налази се сићушни мишић. У тренутку хладноће или изненадне опасности, нервни импулс удара у милионе ових мишића истовремено. Они се грче, повлаче корен и усправљају длачицу. За наше прапретке, који су имали густо и дебело крзно, ово је био савршен механизам: подигнуто крзно је заробљавало слој ваздуха који се загревао и служио као врхунски топлотни изолатор против хипотермије.<br><br>
  Истовремено, у тренутку страха, надувано крзно је чинило да тело изгледа много веће и масивније, служећи као тактика блефирања и застрашивања предатора (баш као што то данас чини уплашена мачка). Иако савремени човек више нема крзно, овај „прастари софтвер“ је остао уписан у нашем генетском коду, па се данас манифестује само као симпатичан ехо преживљавања наших предака.`,
