  audioText: "Физика и хемија пржења црног лука на врелом тигању. Када убацимо сецкани лук у врело уље, вода из ћелија нагло кључа, стварајући милионе микроексплозија паре које производе препознатљив звук цврчања.",
  text: `<b>Физика и хемија пржења црног лука на врелом тигању</b><br><br>
  Када припремамо омиљени ручак и ставимо сецкани црни лук на врело уље, тигань одмах испуњава гласно и познато цврчање. Иза овог звука не стоји пржење самог поврћа, већ насилна и бурна физика воде која се налази унутар биљних ћелија.<br><br>
  Свеж црни лук се састоји од скоро 90% воде, која је унутар његових ћелија закључана под такозваним <em>тургорским притиском</em>, правећи од сваке ћелије минијатурни напумпани водене балон. Уља у тигању се загревају на 180 °Ц, далеко изнад тачке кључања воде од 100 °Ц. Онамог тренутка када лук додирне уље, та вода доживљава екстремни термички шок и тренутно прелази у пару, ширећи своју запремину преко 1.600 пута.<br><br>
  Ово нагло ширење буквално разноси ћелијске зидове лука изнутра. Водена пара се пробија кроз слој врелог уља, а наше ухо региструје милионе сићушних микроексплозија у секунди као јединствени непрекидни шум цврчања. Истовремено, ова висока температура разлаже оштра сумпорна једињења лука у нова, слађа и комплекснија ароматска једињења која дају савршен укус храни.`,
