  text: `<b>Како од песка настаје провидно стапло — хемија, физика и илузија невидљивости</b><br><br>
  Поглед кроз прозор на свет споља делује као нешто сасвим обично, али са тачке гледишта науке, то је невероватан научни парадокс. Рука осећа чврсту баријеру, али око види само празан простор. Како је могуће да од обичног кварцног песка (силицијум-диоксида) добијемо савршено провидну материју?<br><br>
  Чист песак има тачку топљења од преко 1.700 °Ц, што је неугодном за сваку индустријску пећ. Зато се у мешавину додаје <em>сода</em> (натријум-карбонат) која делује као топитељ и снижава тачку топљења на око 1.500 °Ц. Међутим, стакло направљено само од песка и соде било би растворљиво у води као обичан шећер. Зато је трећи кључни састојак <em>кречњак</em>, који служи као хемијски стабилизатор и даје му трајну водоотпорност.<br><br>
  Када се ова смеша растопи у ужареној пећи, настаје густа, лепљива и високо вискозна течност налик на густи сируп. Приликом наглог хлађења, молекулима се одузима време да се организују у правилну кристалну решетку (као што је случај код непрозирног леда или снега). Уместо тога, они се замрзавају у хаотичном, али стабилном распореду течности, постајући <em>аморфна чврста материја</em>. Пошто нема кристалних граница и ивица које би ломиле и расипале светлост, фотони несметано пролазе кроз стакло, стварајући илузију потпуне невидљивости.`,
