  text: `<b>Зашто се мед никада не квари и како пркоси миленијумима</b><br><br>
  Једно од најфасцинантнијих открића у египатским гробницама јесте проналазак тегли са медом старим преко три хиљаде година, који је остао потпуно јестив. Ова невероватна дуговечност није резултат само пустињске климе, већ јединствене физичко-хемијске структуре самог меда.<br><br>
  Свеж нектар који пчеле сакупљају садржи и до 80% воде. Међутим, вредне пчеле махањем крилима стварају снажне струје ваздуха и исушују нектар све док проценат влаге не падне испод 18%. Због тога је мед изразито <em>хигроскопан</em> — он тако снажно привлачи воду да би свака бактерија или микроорганизам који у њега доспе остао потпуно дехидриран. Овај процес, познат као <em>плазмолиза</em>, физички исисава воду из микроба и уништава га.<br><br>
  Поред чисте суше, мед се брани и својом киселошћу (pH између 3 и 4,5), као и ензимом <em>глукоза-оксидазом</em> који пчеле додају у нектар, а који производи природни водоник-пероксид. Овај троструки оклоп — дехидрација, кисела средина и пероксид — чини мед неуништивим природним антибиотиком на који бактерије ни након неколико миленијума нису успеле да развију отпорност.`,
