  text: `<b>Зашто мозак пере отпад док спавамо — биологија, чишћење и неурологија сна</b><br><br>
  Модерно друштво часто посматра спавање као препреку за продуктивност и пуко пасивно искључивање система. Међутим, физиолошки гледано, сан је најсложенији и највреднији процес генералног ремонта који се одвија у нашем телу. Уместо гашења светла у гаражи, мозак током сна почиње да ради као високотехнолошки ауто-сервис.<br><br>
  Док смо будни, наш мозак константно троши око 20% укупне енергије тела. Метаболичка активност неурона ствара опасне отпадне протеине, међу којима је најпознатији <em>бета-амилоид</em>. Пошто је током дана мозак преоптерећен дневним задацима, а његове ћелије набрекле од крви, прање и испирање ових токсина тада су физички немогући.<br><br>
  Тек када утонемо у дубок сан, парасимпатички нервни систем преузима контролу, а мождане ћелије (неурони) се физички скупљају за невероватних 60%. Овај спектакуларан потез отвара међућелијске просторе кроз које почиње да струји цереброспинална течност, вођена <em>глимфатичким системом</em>. Ова ноћна хидраулична праона темељно испира накупљен отпад. Кофеин овај процес не чисти — он само блокира рецепторе умора и гаси лампице упозорења, остављајући нас да сутрадан функционишемо у сопственом метаболичком отпаду („магла у глави“).`,
