  text: `<b>Како настаје мирис прве кише (Петрикор)</b><br><br>
  Да ли сте икада осетили тај посебан, изузетно пријатан мирис у ваздуху непосредно пред летњу кишу или тренутно након што она падне на суву земљу? Научно име за овај феномен је <em>петрикор</em> (од грч. <em>petra</em> — камен и <em>ichor</em> — етерична крв богова).<br><br>
  Овај мирис није само пука романтика, већ права хемијска симфонија коју чине два кључна састојка. Први су биљна уља која битке за преживљавање током сушних дана луче у земљу око свог корена као „знак стоп“ који спречава прерано клијање семена. Други састојек је <em>геосмин</em> — органско једињење које производе корисне земљисне бактерије (стрептомицете) када су под стресом од суше.<br><br>
  Током сушних дана, ови мириси су „закључани“ у прашини и глини као у сефу. Међутим, када капи кише ударе у суву земљу брзином од око 10 метара у секунду, оне делују попут минијатурних метеорита. Ударом стварају сићушне мехуриће ваздуха који избијају на површину капи и пуцају, испаљујући милионе сићушних капљица (аеросола) у ваздух. Ветрови их затим разводе пре него што пљусак уопште стигне до нас, а наш мозак овај мирис еволутивно препознаје као сигнал свежине и воде, отпуштајући допамин.`,
