  audioText: "Зашто кишне глисте излазе на асфалт после кише. Кишне глисте излазе на површину након кише не зато што се давде у води, већ због комбинације страха од кртица које стварају исте вибрације и потребе за миграцијом.",
  text: `<b>Зашто кишне глисте излазе на асфалт после кише</b><br><br>
  Популарно је мишљење да кишне глисте након олује излазе на асфалт зато што им поплављени подземни тунели одузимају кисеоник и оне почињу да се давде. Ипак, права истина је много занимљивија и комплекснија.<br><br>
  Глисте уопште немају плућа, већ дишу преко целе површине своје сопствене влажне коже (процес кутикуларног дисања). Кисеоник мора прво да се раствори у танком слоју слузи да би доспео до крвотока. Због тога оне заиста не воле суво време. Међутим, када почне јак пљусак, вода која надире у земљу насилно истискује ваздух, али глисте могу дуго да преживе у влажној земљи или да користе растворени кисеоник.<br><br>
  Главни разлог зашто оне масовно излазе на површину јесте — <em>паника од кртица</em>! Ритмични удари милиона тешких кишних капи о површину тла производе вибрације исте ниске фреквенције као копање кртице, њиховог главног подземног непријатеља. Глисте у паници беже нагоре, али их на сувом асфалту често чекају птице и сунце, због чега је овај бег често пут у једном смеру.`,
