  text: `<b>Зашто пчеле граде баш шестоугаоно саће</b><br><br>
  Пчелиње саће представља једно од најфасцинантнијих природних решења која спајају биологију, математику и инжењерство. За изградњу саћа пчелама је потребан восак, који оне саме производе у свом телу преко посебних жлезда. Међутим, овај восак има велику цену: да би произвеле само један килограм воска, пчеле морају да потроше чак осам килограма сопствених драгоцених залиха меда. Због тога је восак најскупља могућа „валута“ у кошници.<br><br>
  Када би пчеле правиле округле ћелије, између њих би остајало много празног простора у облику звездастих џепова. Заливање свих тих шупљина додатним воском довело би колонију до брзог енергетског банкрота. Са друге стране, правилне троуглове или квадрате пчеле могу да сложе без пукотина, али они троше много више материјала и имају лошији однос обіма и унутрашње запремине.<br><br>
  Математички савршени <em>шестоугао (хексагон)</em> представља победничко решење. Он пружа највећу могућу запремину за смеštaj меда и ларви уз минималну потрошњу воска. Захваљујући концепту „100% дељења зидова“, свака шестоугаона ћелија дели своје зидове са суседним, тако да ни један једини микрограм воска није дуплиран, а спојеви под углом од 120 степени у облику слова „Y“ савршено трпе огроман хидростатички притисак тешког меда.`,
