  text: `<b>Како заправо настају муња и гром — физика, електростатика и акустика</b><br><br>
  Масивни олујни облаци, познати као <em>кумулонимбуси</em>, могу се пружати у висину и преко 10 или 15 километара. Унутар ових облака влада права турбуленција, налик на подivљалу машину за прање веша. Иако је споља летњи дан, на огромним висинама температура пада дубоко испод нуле, па се сударају кристали леда и капљице воде.<br><br>
  Баш попут трљања балона о косу, трење и судари унутар облака стварају огромно раздвајање статичког електрицитета. Лакши позитивни кристали одлазе на врх облака, док тежи негативни делови падају на дно. Облак тако постаје џиновска лебдећа батерија. Пошто је ваздух у нормалним условима добар изолатор, долази до тренутка када разлика у набоју постаје толико екстремна да изолација пуца и ослобађа се џиновска електрична варница — <em>муња</em>.<br><br>
  Канал кроз који муња прође у делићу секунде се загрева до невероватних 30.000 °Ц (што је око пет пута топлије од површине Сунца), претварајући ваздух у плазму. Ово експлозивно ширење ваздуха ствара суперсонични ударни талас који чујемо као гром. Због огромне разлике у брзини светлости и звука, најпре видимо бљесак, а потом бројањем секунди и дељењем са три можемо прецизно израчунати удаљеност олује у километрима.`,
