  text: `<b>Прве Олимпијске игре и свето примирје у античкој Грчкој</b><br><br>
  Прве античке Олимпијске игре одржане су 776. године пре нове ере у светом месту Олимпији, у част врховног божанства — Зевса. За старе Грке, Зевс није био апстрактна филозофска идеја, већ застрашујући и моћни ентитет који управља олујама, животом и смрћу. Зато физички напор спортиста није био само обична забава, већ облик молитве и жива жртва принета на олтар божанству.<br><br>
  У доба када је сурова планинска географија Грчке била пресечена сталним међусобним ратовима полиса, појавила се институција светог примирја — <em>екехеирије</em>. Овај сакрални закон гарантовао је потпуну безбедност свим спортистима и гледаоцима на путу кроз непријатељске територије. Напад на путнике ка Олимпији сматрао се директним богохуљењем против Зевса, што је водило у војну одмазду свих грчких држава и потпуну друштвену екскомуникацију прекршиоца.<br><br>
  Као награду, победници нису добијали злато ни новац, већ скромни венац од маслинових гранчица. У свету где је злато лако могло бити оштећено или претопено у оружје, олимпијски венац је доносио бесмртну славу. Победници су се враћали у своје градове кроз рушевине сопствених зидина — симболично порушених јер граду чији грађани дају такве хероје бедеми више нису потребни — уз доживотне почасне привилегије и бесплатан улог на државном рачуну.`,
